hits = globals()['LAUNCHER_HITS']
allh = hits['dex']+hits['arsc']
import re

def show(title, pat, limit=120):
    arr=[s for s in allh if re.search(pat,s,re.I)]
    print(f'\n## {title} ({len(arr)})')
    for s in sorted(arr, key=str.lower)[:limit]:
        print(' ', s)
    if len(arr)>limit:
        print(f'  ... {len(arr)-limit} more')
    return arr

